"""Produce a traceable vacancy table and counts from manually verified source facts."""
from collections import Counter
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
base=ROOT/'docs/kt3'
rows=json.loads((base/'vacancies.json').read_text())
counts=Counter(tag for row in rows for tag in dict.fromkeys(row['required_tags']))
optional=Counter(tag for row in rows for tag in dict.fromkeys(row['optional_tags']))
lines=['# Анализ вакансий для команды проекта КТ3','',
'Дата просмотра: **21 ноября 2026 года**. Выборка: 10 вакансий десяти компаний, девять на Хабр Карьере и одна на сайте работодателя. Три позиции относятся к Java-разработке, две — к тестированию, три — к системному анализу, две — к эксплуатации. Это целевая учебная выборка для проекта учёта сборки серверов, а не статистически репрезентативная оценка всего рынка. Включены разные уровни: начальные позиции показывают ближайший вход, опытные — направления роста. Вакансия V07 относится к Минску, остальные — к российскому рынку и удалённой работе.', '',
'Зарплаты указаны только там, где их опубликовал работодатель. Автоматические оценки Хабр Карьеры «похожие специалисты получают» в таблицу не перенесены. Указанный грейд не заменяет требование к стажу.', '',
'| ID | Должность и компания | Просмотр и источник | Технологии и навыки | Опыт | Условия |',
'| --- | --- | --- | --- | --- | --- |']
for r in rows:
    lines.append(f"| {r['id']} | {r['title']} — {r['company']} | {r['viewed']}; [{r['platform']}]({r['url']}) | {r['requirements']} | {r['experience']} | {r['conditions']} |")
lines+=['','## Частота упоминаний в требованиях','',
'Каждый навык учитывается не более одного раза в одной вакансии. В основной счётчик включены раздел требований и теги квалификации карточки. Отдельно сохранены преимущества и контекст проекта. Категория «Контейнеризация» объединяет Docker/Kubernetes; «Git/GitLab» — явно названные инструменты. Общее «система контроля версий» не превращается в Git. SQL считается только при явном упоминании SQL, а не по одному названию PostgreSQL. Spring в V02 — один из допустимых вариантов фреймворка, а не безусловное требование именно Spring.', '',
'| Навык или группа | Вакансий из 10 | ID вакансий |', '| --- | ---: | --- |']
for tag,n in counts.most_common():
    ids=', '.join(r['id'] for r in rows if tag in r['required_tags'])
    lines.append(f'| {tag} | {n} | {ids} |')
lines+=['','Преимущества, не включённые в основной счётчик: '+ '; '.join(f'{tag} — {n}/10' for tag,n in optional.items())+'.','',
'## Интерпретация для проекта','',
'Java и SQL прямо встречаются в требованиях пяти вакансий из десяти. Для текущей программы важнее сначала закрепить коллекции, контракты объектов и запросы к данным, чем добавлять распределённую инфраструктуру. REST/API также встречается в пяти позициях: это следующий шаг после устойчивой CLI-версии и подключения БД на КТ4. Git/GitLab упомянуты в пяти вакансиях, CI/CD — в четырёх; воспроизводимая сборка и автоматические проверки связывают разработку с эксплуатацией.', '',
'Все три аналитические позиции требуют UML и BPMN. Это подтверждает связь диаграмм КТ2/КТ3 с рабочими задачами аналитика. Обе QA-позиции используют Java и JUnit/TestNG; автономные assert-проверки текущего проекта полезны как старт, но не заменяют практику тестового фреймворка. Linux/Unix упомянуты в трёх вакансиях, в том числе у тестировщика; чтение логов и запуск приложения на сервере нужны не только DevOps-инженеру.', '',
'Восемь позиций ориентированы на опытных специалистов, если считать явно заявленные Middle/Senior и требования от трёх лет; V01 и V05 дают ориентир на начало карьеры. Коммерческий стаж из вакансий не заменяется учебным проектом: приоритеты ниже описывают подготовку к следующему уровню, а не обещание немедленного соответствия всем позициям.', '',
'## Уточнения к кодированию требований','']
for r in rows:lines.append(f"- **{r['id']}**: {r['note']}")
(base/'market.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
(base/'market_counts.json').write_text(json.dumps({'required':dict(counts),'optional':dict(optional)},ensure_ascii=False,indent=2)+'\n')
print(dict(counts))
